// Extract event info, validate HMAC SHA-256 signature (fail-closed), and parse task key
let rawPayload = '';
let body = {};

if (typeof $json.rawBody === 'string') {
  rawPayload = $json.rawBody;
  try { body = JSON.parse($json.rawBody); } catch (e) { body = (typeof $json.body === 'object' && $json.body) ? $json.body : {}; }
} else if (typeof $json.body === 'string') {
  rawPayload = $json.body;
  try { body = JSON.parse($json.body); } catch (e) { body = {}; }
} else if (typeof $json.body === 'object' && $json.body !== null) {
  body = $json.body;
  rawPayload = JSON.stringify(body);
} else if (typeof $json === 'object') {
  body = $json;
  rawPayload = JSON.stringify(body);
}

const headers = $json.headers || {};
const action = body.action || 'push';
const pr = body.pull_request || {};
const issue = body.issue || {};
const repo = body.repository || {};
const isMerged = Boolean(pr.merged);

// An `issues` event carries `issue` and no `pull_request`. Gitea also sends an
// `issue` object for pull-request comment events, where `issue.pull_request` is
// populated -- excluded here, or a PR comment would be treated as a new issue.
const isIssueEvent = Boolean(body.issue && !body.pull_request && !issue.pull_request);

const title = pr.title || issue.title || body.head_commit?.message || '';
const branch = pr.head?.ref || body.ref || '';
const prUrl = pr.html_url || '';
const issueUrl = issue.html_url || '';
const issueNumber = issue.number || body.number || null;
const repoOwner = repo.owner?.login || repo.owner?.username || (repo.full_name || '').split('/')[0] || '';
const repoName = repo.name || '';

// Match task key pattern (e.g. IDP-035, GITOPS-003, APP-CONFIG-008).
//
// The AREA may itself be hyphenated -- `APP-CONFIG`, `CI-GATE`, `SEC-VIKUNJA`
// are live on this board. A single `[A-Z]{2,10}-(\d+)` truncates those to
// `CONFIG-008` / `GATE-018` / `VIKUNJA-001`, because `\b` lets the match restart
// after the first hyphen. Measured 2026-09-05 over 300 real issue titles: 25 of
// the 256 that matched were truncated, spanning five whole AREAs.
//
// The truncation could not surface as a failed lookup, which is why it survived:
// `?s=` is a SUBSTRING search, so `?s=CONFIG-008` still finds a task titled
// `APP-CONFIG-008: ...`. It surfaces only as a collision between two AREAs
// sharing a final segment -- and by then two tickets share one key.
//
// Repeating the segment keeps the whole AREA. Verified over the same 300 titles:
// the set of titles that match is IDENTICAL (256), so no event starts or stops
// being processed; 25 of them merely carry their full key now.
const match = (title + ' ' + branch).toUpperCase().match(/\b([A-Z]{2,10}(?:-[A-Z]{2,10})*)-(\d+)\b/);
const taskKey = match ? match[0] : null;
const taskId = match ? parseInt(match[2], 10) : null;

// HMAC validation: strictly fail-closed
const isGitHub = Boolean(headers['x-hub-signature-256']);
const isGitea = Boolean(headers['x-gitea-signature']);
const sig = headers['x-hub-signature-256'] || headers['x-gitea-signature'] || '';
const secret = (isGitHub && $env.GITHUB_WEBHOOK_SECRET) || (isGitea && $env.GITEA_WEBHOOK_SECRET) || $env.FORGE_WEBHOOK_SECRET || '';
let isValidSig = false;

if (secret && sig && rawPayload) {
  const crypto = require('crypto');
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(rawPayload);
  const hexDigest = hmac.digest('hex');
  isValidSig = (sig === 'sha256=' + hexDigest || sig === hexDigest);
}

let targetBucket = 'In Progress';
let isDone = false;
if (action === 'closed' && isMerged) {
  targetBucket = 'Done';
  isDone = true;
} else if (['opened', 'synchronize', 'reopened'].includes(action)) {
  targetBucket = 'In Review';
  isDone = false;
}

// The create-path's trigger floor. It mirrors `add-to-project.yml`, the workflow
// being retired, which fires on `opened` and `reopened` and nothing else -- so
// the invariant ported here is exactly the one that existed, not a wider one.
// `closed` and `edited` deliberately fall through to a 200 without creating:
// creating a task from a closing issue would resurrect work, not track it.
const CREATE_ACTIONS = ['opened', 'reopened'];
const isCreateCandidate = Boolean(taskKey && isValidSig && isIssueEvent && CREATE_ACTIONS.includes(action));

return [{
  json: {
    taskKey: taskKey,
    taskId: taskId,
    action: action,
    isMerged: isMerged,
    isDone: isDone,
    targetBucket: targetBucket,
    prUrl: prUrl,
    title: title,
    issueUrl: issueUrl,
    issueNumber: issueNumber,
    repoOwner: repoOwner,
    repoName: repoName,
    isIssueEvent: isIssueEvent,
    isCreateCandidate: isCreateCandidate,
    hasTask: Boolean(taskKey && isValidSig),
    isValidSig: isValidSig
  }
}];

// Resolve matched task ID from search results; do not guess random IDs
const searchResults = Array.isArray($json) ? $json : ($json.data || []);
const event = $('Parse Forge Event').first().json;
let resolvedTaskId = null;

if (searchResults.length > 0 && searchResults[0].id) {
  resolvedTaskId = searchResults[0].id;
}

return [{
  json: {
    ...event,
    taskId: resolvedTaskId,
    hasMatchedTask: Boolean(resolvedTaskId)
  }
}];

// Decide whether the issue's task already exists -- by an EXACT key match, never
// by "the search returned something".
//
// `GET /tasks?s=` is a SUBSTRING search. The pull-request path's sibling node
// takes `searchResults[0].id`, which is safe there only because it is looking
// for a task it expects to find. Reused here it would be a silent bug: searching
// `TOOL-035` also matches a task titled `TOOL-0350: ...`, so the create path
// would conclude TOOL-035 already exists and never create it -- and answer 200.
const event = $('Parse Forge Event').first().json;
const raw = Array.isArray($json) ? $json : ($json.data || []);
const results = Array.isArray(raw) ? raw : [];

// A search that ERRORED is not a search that found nothing. `continueOnFail` on
// the request node turns a 401/timeout into an item carrying `error`, which is
// indistinguishable from an empty result set unless it is checked. Creating on
// that would duplicate a task that already exists.
const searchFailed = Boolean($json.error) || !Array.isArray(raw);

const key = (event.taskKey || '').toUpperCase();
const exact = results.filter(t => {
  const title = (t.title || '').toUpperCase();
  if (!key || !title.startsWith(key)) return false;
  // Reject only a continuing DIGIT: `TOOL-035` must not match `TOOL-0350`, but
  // must match both `TOOL-035: slug` and `TOOL-035-slug`, since the board's ID
  // convention is `AREA-NNN-slug` and the issue title renders it `AREA-NNN: ...`.
  return !/[0-9]/.test(title.charAt(key.length));
});

// AC1 by construction, not by convention. The key is extracted from anywhere in
// the title, so an issue called `fix the TOOL-035 thing` would otherwise produce
// a task whose title does not START with the key -- and `?s=` would still find
// it, right up until a second AREA collides. Prefixing when it is absent makes
// the join key a property of every task this path creates.
const rawTitle = (event.title || '').trim();
const taskTitle = rawTitle.toUpperCase().startsWith(key) ? rawTitle : (event.taskKey + ': ' + rawTitle);

return [{
  json: {
    ...event,
    searchFailed: searchFailed,
    existingTaskId: exact.length > 0 ? exact[0].id : null,
    taskAlreadyExists: exact.length > 0,
    notCreatedReason: exact.length > 0 ? 'task already exists in vikunja' : null,
    taskTitle: taskTitle,
    taskDescription: '<p>Forge issue: <a href="' + event.issueUrl + '">'
      + event.repoOwner + '/' + event.repoName + '#' + event.issueNumber + '</a></p>'
  }
}];

// Resolve which Vikunja project the new task belongs to, from the forge payload.
//
// There is NO numeric fallback. `slack-task-capture` defaults to `projectId = 1`
// because a human typed the command and can see where it landed; nothing watches
// a webhook, so the same default would file issues into whatever project happens
// to be first, invisibly and forever.
//
// Declaring the fallback in `n8n-config` was considered and rejected: that
// ConfigMap is a plain resource, not a `configMapGenerator` entry, and n8n reads
// env once at container start -- so the key would change, Argo CD would report
// Synced/Healthy, and the pod would keep the old value (lesson-404). Resolving
// from the payload needs no new config surface at all.
//
// Unresolved therefore means DO NOT CREATE, and the caller answers non-2xx so
// the forge records a failed delivery. That is the whole point: a task filed in
// the wrong project looks exactly like a task filed correctly.
const event = $('Extract Issue Task Match').first().json;
const raw = Array.isArray($json) ? $json : ($json.data || []);
const projects = Array.isArray(raw) ? raw : [];

const norm = s => (s || '').toString().trim().toLowerCase();

// Repository name first (a repo with its own project is the more specific
// match), then the owning organisation -- `kubelab`, `personal`, `teledyne` are
// the units `vikunja_reconciler.DEFAULT_NAMESPACES` declares.
const byName = projects.find(p => norm(p.title) === norm(event.repoName));
const byOwner = projects.find(p => norm(p.title) === norm(event.repoOwner));
const picked = byName || byOwner || null;

return [{
  json: {
    ...event,
    projectId: picked ? picked.id : null,
    projectTitle: picked ? picked.title : null,
    projectLookupFailed: Boolean($json.error) || !Array.isArray(raw),
    readyToCreate: Boolean(picked && picked.id && !event.searchFailed)
  }
}];
